-- D14 L2: 取与 A001 相交的高压燃气管线，先裁剪到 A001，再分别缓冲 50 米并合并。计算各水管在该影响范围且在 A001 内的长度（米），按长度降序、同长按水管编码升序输出全部水管及总长度。保留非空的零长度边界接触记录。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 严格先裁剪高压管线再缓冲；水管需同时位于影响范围和 A001；点接触保留，空几何剔除。
WITH a AS (SELECT geom FROM gis_lab.construction_areas WHERE code='A001'), high AS (SELECT ST_Intersection(g.geom,a.geom) AS geom FROM gis_lab.gas_pipelines g CROSS JOIN a WHERE g.pressure_level='高压' AND ST_Intersects(g.geom,a.geom)), influence AS (SELECT ST_UnaryUnion(ST_Collect(ST_Buffer(geom,50,'quad_segs=8'))) AS geom FROM high), water_cut AS (SELECT w.code,ST_Intersection(ST_Intersection(w.geom,i.geom),a.geom) AS geom FROM gis_lab.water_pipelines w CROSS JOIN influence i CROSS JOIN a WHERE ST_Intersects(w.geom,i.geom)), water_values AS (SELECT code,ST_Length(geom) AS value FROM water_cut WHERE NOT ST_IsEmpty(geom)) SELECT jsonb_build_object('groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('group',jsonb_build_object('source_code',code),'value',value,'feature_count',1) ORDER BY value DESC,code COLLATE "C") FROM water_values),'[]'::jsonb),'unit','meter','total_length',jsonb_build_object('value',(SELECT COALESCE(sum(value),0) FROM water_values),'unit','meter','measure','length','measure_srid',3857,'feature_count',(SELECT count(*) FROM water_values))) AS answer;
